hooks.command:
cd "${CLAUDE_PROJECT_DIR:-.}" || exit 0
[ -z "$(git status --porcelain -- frontend backend shared api 2>/dev/null)" ] && exit 0
out=$(npm run typecheck 2>&1) || { printf '%s' "$out" | tail -30 | jq -Rs '{decision:"block",reason:("typecheck failed: fix before finishing:\n"+.)}'; exit 0; }
out=$(npm run lint 2>&1) || { printf '%s' "$out" | tail -30 | jq -Rs '{decision:"block",reason:("lint failed: fix before finishing:\n"+.)}'; exit 0; }
out=$(npm run test:coverage 2>&1) || { printf '%s' "$out" | tail -30 | jq -Rs '{decision:"block",reason:("tests or coverage failed: fix before finishing:\n"+.)}'; exit 0; }
out=$(npm run build 2>&1) || { printf '%s' "$out" | tail -30 | jq -Rs '{decision:"block",reason:("build failed: fix before finishing:\n"+.)}'; exit 0; }
out=$(npm run size -w frontend 2>&1) || { printf '%s' "$out" | tail -30 | jq -Rs '{decision:"block",reason:("the first-load JS budget failed: fix before finishing:\n"+.)}'; exit 0; }
exit 0
